// ---------- Thenable builder ----------
function createBuilder(tableName) {
  const filters = [];
  let rows = getTable(tableName);

  const apply = () => {
    let list = [...rows];
    filters.forEach(f => {
      if (f.type === 'eq') list = list.filter(r => r[f.col] === f.val);
      else if (f.type === 'gte') list = list.filter(r => new Date(r[f.col]) >= new Date(f.val));
      else if (f.type === 'lte') list = list.filter(r => new Date(r[f.col]) <= new Date(f.val));
      else if (f.type === 'not') list = list.filter(r => r[f.col] !== f.val);
      else if (f.type === 'is') list = list.filter(r => r[f.col] === null);
    });
    return list;
  };

  const ops = {
    eq: (col, val) => { filters.push({ type: 'eq', col, val }); return ops; },
    gte: (col, val) => { filters.push({ type: 'gte', col, val }); return ops; },
    lte: (col, val) => { filters.push({ type: 'lte', col, val }); return ops; },
    not: (col, val) => { filters.push({ type: 'not', col, val }); return ops; },
    is: (col, val) => { filters.push({ type: 'is', col, val }); return ops; },
    order: (col, { ascending = true } = {}) => {
      let list = apply();
      list.sort((a, b) => (a[col] > b[col] ? 1 : -1) * (ascending ? 1 : -1));
      // return a thenable with limit
      const ordered = {
        limit: (n) => ({ data: list.slice(0, n), error: null }),
        then: (resolve) => resolve({ data: list, error: null }),
      };
      return ordered;
    },
    single: () => {
      const list = apply();
      return { data: list[0] || null, error: null };
    },
    maybeSingle: () => {
      const list = apply();
      return { data: list[0] || null, error: null };
    },
    limit: (n) => {
      const list = apply().slice(0, n);
      return Promise.resolve({ data: list, error: null });
    },
    then: (resolve) => {
      resolve({ data: apply(), error: null });
    },
  };

  return ops;
}

export const supabase = {
  from: (table) => {
    // read actions
    const builder = createBuilder(table);
    // attach insert/update/delete
    return {
      select: () => builder,
      insert: (data) => {
        const arr = Array.isArray(data) ? data : [data];
        const newRows = arr.map(d => ({ id: generateID(), ...d }));
        const current = getTable(table);
        const updated = [...current, ...newRows];
        saveTable(table, updated);
        return {
          select: () => ({
            single: () => ({ data: newRows[0], error: null }),
            then: (resolve) => resolve({ data: newRows, error: null }),
          }),
          single: () => ({ data: newRows[0], error: null }),
          then: (resolve) => resolve({ data: newRows, error: null }),
        };
      },
      update: (data) => ({
        eq: (col, val) => {
          const rows = getTable(table);
          const updated = rows.map(r => r[col] === val ? { ...r, ...data } : r);
          saveTable(table, updated);
          return { error: null };
        },
        in: (col, vals) => {
          const rows = getTable(table);
          const updated = rows.map(r => vals.includes(r[col]) ? { ...r, ...data } : r);
          saveTable(table, updated);
          return { error: null };
        },
      }),
      delete: () => ({
        eq: (col, val) => {
          const rows = getTable(table);
          const filtered = rows.filter(r => r[col] !== val);
          saveTable(table, filtered);
          return { error: null };
        },
      }),
      upsert: (data) => {
        const rows = getTable(table);
        if (Array.isArray(data)) {
          data.forEach(d => {
            const idx = rows.findIndex(r => r.id === d.id);
            if (idx >= 0) rows[idx] = d;
            else rows.push({ id: generateID(), ...d });
          });
        } else {
          const idx = rows.findIndex(r => r.id === data.id);
          if (idx >= 0) rows[idx] = data;
          else rows.push({ id: generateID(), ...data });
        }
        saveTable(table, rows);
        return { error: null };
      },
    };
  },
  auth: {
    signInWithPassword: async ({ email, password }) => {
      const staff = getTable('staff');
      const user = staff.find(u => u.email === email && u.pin_code === password);
      if (!user) return { error: { message: 'Invalid credentials' } };
      localStorage.setItem('local_user', JSON.stringify(user));
      return { data: { user }, error: null };
    },
    signOut: async () => { localStorage.removeItem('local_user'); return { error: null }; },
    getSession: async () => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      if (!user) return { data: { session: null } };
      return { data: { session: { user, access_token: 'offline', refresh_token: 'offline' } } };
    },
    onAuthStateChange: (cb) => {
      const user = JSON.parse(localStorage.getItem('local_user') || 'null');
      setTimeout(() => cb('SIGNED_IN', { user }), 10);
      return { data: { subscription: { unsubscribe: () => {} } } };
    },
    setSession: async () => ({ error: null }),
    signUp: async ({ email, password, options }) => {
      const staff = getTable('staff');
      const newUser = { id: generateID(), email, pin_code: password,
        full_name: options?.data?.full_name || 'New User', role: 'cashier', is_active: true, store_id: null };
      saveTable('staff', [...staff, newUser]);
      return { data: { user: newUser }, error: null };
    },
  },
  storage: {
    from: () => ({
      upload: async () => ({ error: null }),
      getPublicUrl: () => ({ data: { publicUrl: '' } }),
    }),
  },
  rpc: () => ({ error: null }),
};
